#include <vector>
#include <queue>
#include <iostream>

std::vector<int> topologicalSort(int V, const std::vector<std::vector<int>>& adj) {
    std::vector<int> inDegree(V, 0);
    for (int u = 0; u < V; ++u) {
        for (int v : adj[u]) inDegree[v]++;
    }

    std::queue<int> q;
    for (int i = 0; i < V; ++i) {
        if (inDegree[i] == 0) q.push(i);
    }

    std::vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);

        for (int v : adj[u]) {
            if (--inDegree[v] == 0) q.push(v);
        }
    }

    if (order.size() != V) {
        std::cerr << "Cycle detected! Topological sort impossible." << std::endl;
        return {};
    }
    return order;
}

vector<int> topoSort(int V, vector<int> adj[]) {
    vector<int> in_degree(V, 0);
    for(int i=0; i<V; i++) {
        for(auto x: adj[i]) in_degree[x]++;
    }
    queue<int> q;
    for(int i=0; i<V; i++) if(in_degree[i] == 0) q.push(i);
    vector<int> ans;
    while(!q.empty()) {
        int node = q.front(); q.pop();
        ans.push_back(node);
        for(auto it: adj[node]) {
            in_degree[it]--;
            if(in_degree[it] == 0) q.push(it);
        }
    }
    // Omitted cycle check, returns partial list if cycle exists
    return ans;
}

// Section C Student - 3-color DFS approach
bool dfs(int u, vector<int>& color, vector<int> adj[], vector<int>& res) {
    color[u] = 1; // GRAY: visiting
    for (int v : adj[u]) {
        if (color[v] == 1) return true; // Cycle detected
        if (color[v] == 0 && dfs(v, color, adj, res)) return true;
    }
    color[u] = 2; // BLACK: visited
    res.push_back(u);
    return false;
}

vector<int> topoSortDFS(int V, vector<int> adj[]) {
    vector<int> color(V, 0), res;
    for (int i = 0; i < V; i++) {
        if (color[i] == 0 && dfs(i, color, adj, res)) {
            cout << "Cycle detected!" << endl;
            return {};
        }
    }
    reverse(res.begin(), res.end());
    return res;
}
